import { useCallback, useEffect, useLayoutEffect, useState } from 'react';

/**
 * 列表状态记忆：档案列表这种"长列表 → 点进资料 → 返回"的路径，返回时必须回到离开前的位置与筛选，
 * 否则每次返回都被拉回最上方，还得重新筛一遍。
 *
 * 为什么不用浏览器自带的 `history.scrollRestoration`：
 * 站点的滚动容器不是 window，而是 `.mobile-shell main`（宽屏同样是它）；浏览器只恢复文档级滚动。
 * 而且从列表进详情时列表会被卸载，恢复的时机也不存在，所以位置只能自己记。
 *
 * 存放在 `sessionStorage`：同一个标签页内返回/刷新都有效，关掉标签页即失效，不污染长期状态。
 */

const KEY_PREFIX = 'museum.list.';

/** 站点真正的滚动容器：`.mobile-shell main`；兜底用文档滚动元素（测试环境/异常布局）。 */
function scroller(): HTMLElement | null {
  const main = document.querySelector<HTMLElement>('.mobile-shell main');
  if (main) return main;
  return (document.scrollingElement as HTMLElement | null) ?? null;
}

function readNumber(key: string): number | null {
  try {
    const raw = window.sessionStorage.getItem(key);
    if (raw === null) return null;
    const value = Number(raw);
    return Number.isFinite(value) ? value : null;
  } catch {
    return null;
  }
}

function writeNumber(key: string, value: number) {
  try {
    window.sessionStorage.setItem(key, String(Math.max(0, Math.round(value))));
  } catch {
    // 隐私模式/配额满：记不住位置不是致命问题，忽略。
  }
}

/**
 * 记住并获得该 key 的滚动位置。
 * 返回的 `save()` 用于"离开列表前明确记一次"（点击资料卡的瞬间），比只依赖 scroll 事件更可靠：
 * 进详情时列表子树会在同一个提交里被替换，卸载阶段的 `scrollTop` 可能已经被夹到 0。
 */
export function useScrollRestoration(key: string, enabled = true) {
  const storageKey = `${KEY_PREFIX}scroll:${key}`;

  // 恢复：等一帧再设。列表高度还没算出来时浏览器会把 scrollTop 夹到 0。
  useLayoutEffect(() => {
    if (!enabled) return;
    const element = scroller();
    const saved = readNumber(storageKey);
    if (!element || saved === null || saved <= 0) return;
    let second = 0;
    const first = window.requestAnimationFrame(() => {
      element.scrollTop = saved;
      // 第二帧补一次：缩略图/字体撑开高度后，同一次赋值可能还落不到位。
      second = window.requestAnimationFrame(() => { element.scrollTop = saved; });
    });
    return () => {
      window.cancelAnimationFrame(first);
      window.cancelAnimationFrame(second);
    };
  }, [enabled, storageKey]);

  const save = useCallback(() => {
    const element = scroller();
    if (element) writeNumber(storageKey, element.scrollTop);
  }, [storageKey]);

  // 记录：滚动时按帧节流写入就够了；卸载时不再写，避免写到已被替换后归零的位置。
  useLayoutEffect(() => {
    if (!enabled) return;
    const element = scroller();
    if (!element) return;
    let frame = 0;
    const onScroll = () => {
      if (frame) return;
      frame = window.requestAnimationFrame(() => {
        frame = 0;
        writeNumber(storageKey, element.scrollTop);
      });
    };
    element.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      element.removeEventListener('scroll', onScroll);
      if (frame) window.cancelAnimationFrame(frame);
    };
  }, [enabled, storageKey]);

  return save;
}

/** 与 useState 同形，但值写进 sessionStorage —— 返回列表时筛选条件、视图模式不被重置。 */
export function useSessionState<T>(key: string, initial: T) {
  const storageKey = `${KEY_PREFIX}state:${key}`;
  const [value, setValue] = useState<T>(() => {
    try {
      const raw = window.sessionStorage.getItem(storageKey);
      if (raw === null) return initial;
      return JSON.parse(raw) as T;
    } catch {
      return initial;
    }
  });
  useEffect(() => {
    try {
      window.sessionStorage.setItem(storageKey, JSON.stringify(value));
    } catch {
      // 同上：存不下不影响使用。
    }
  }, [storageKey, value]);
  return [value, setValue] as const;
}

/** 列表状态记忆的键（供测试与调试引用，避免在代码里散落字符串）。 */
export const listStateKeys = {
  archive: 'archive',
} as const;

/** 供测试/调试清零：只清本模块写入的键。 */
export function clearListState() {
  try {
    for (const key of Object.keys(window.sessionStorage)) {
      if (key.startsWith(KEY_PREFIX)) window.sessionStorage.removeItem(key);
    }
  } catch {
    // 忽略
  }
}
