import { FileImage, FileText, Film, PackageOpen, Search } from 'lucide-react';
import { useMemo } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import type { ResourceConfig } from '../../config/schema';
import { resourceScope } from '../../config/schema';
import { listStateKeys, useScrollRestoration, useSessionState } from '../../shared/listState';
import { ResourceViewer } from './ResourceViewer';
import { prefetchResourceViewer } from '../../shared/prefetch';

const kindFilters: Array<{ value: ResourceConfig['kind'] | 'all'; label: string }> = [
  { value: 'all', label: '全部' },
  { value: 'image', label: '图片' },
  { value: 'video', label: '视频' },
  { value: 'pdf', label: 'PDF' },
  { value: 'model', label: '模型' },
];

/** 归属：这份资料讲的是"谁"的事（设备 / 场地 / 项目与机构）。 */
const scopeFilters = [
  { value: 'all', label: '全部' },
  { value: 'device', label: '设备' },
  { value: 'site', label: '场地' },
  { value: 'program', label: '项目' },
] as const;
type ScopeFilter = (typeof scopeFilters)[number]['value'];

/** 视图：平铺总览 / 按年代 / 按策展专辑。三者是同一份数据的三种排布，不复制数据。 */
const views = [
  { value: 'grid', label: '总览' },
  { value: 'timeline', label: '年代' },
  { value: 'collection', label: '专辑' },
] as const;
type ArchiveView = (typeof views)[number]['value'];

const UNKNOWN_YEAR_LABEL = '未标注年代';
const UNCATALOGUED_LABEL = '未编入专辑';

/** 归属筛选按**主层级**判定（关系可以跨级，层级只有一个）：项目级资料即使与设备有关，也不会被算进「设备」。 */
function matchesScope(resource: ResourceConfig, scope: ScopeFilter) {
  return scope === 'all' || resourceScope(resource) === scope;
}

function ResourceCard({ resource, meta, onOpen }: { resource: ResourceConfig; meta: string; onOpen(): void }) {
  const Icon = resource.kind === 'image' ? FileImage : resource.kind === 'video' ? Film : resource.kind === 'model' ? PackageOpen : FileText;
  return (
    <button
      type="button"
      onPointerEnter={() => prefetchResourceViewer(resource.kind)}
      onFocus={() => prefetchResourceViewer(resource.kind)}
      onClick={onOpen}
      aria-label={`打开${resource.title}`}
    >
      <span><Icon /></span>
      <div>
        <strong>{resource.title}</strong>
        {meta && <span className="archive-card-meta">{meta}</span>}
        <small>{resource.description}</small>
      </div>
    </button>
  );
}

export function ArchivePage() {
  const { resourceId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { config, repository } = useMuseumConfig();
  // 筛选/视图写进 sessionStorage：从资料详情返回时，列表还是离开前那一屏，不会白筛一遍。
  const [query, setQuery] = useSessionState('archive.query', '');
  const [kind, setKind] = useSessionState<ResourceConfig['kind'] | 'all'>('archive.kind', 'all');
  const [eventType, setEventType] = useSessionState('archive.eventType', 'all');
  const [scope, setScope] = useSessionState<ScopeFilter>('archive.scope', 'all');
  const [view, setView] = useSessionState<ArchiveView>('archive.view', 'grid');
  const selected = resourceId ? repository.getResource(resourceId) : undefined;
  // 只有列表在显示时才恢复/记录滚动位置；详情页有自己的滚动。
  const saveScroll = useScrollRestoration(listStateKeys.archive, !selected);
  const openResource = (id: string) => {
    // 先记一次位置再跳：进详情时列表子树会在同一个提交里被替换，之后再读 scrollTop 可能已经是 0。
    saveScroll();
    navigate(`/archive/${id}`);
  };

  // 事件类型标签来自配置里的受控词表（词表改了，这里跟着变，不用改代码）。
  const eventLabels = useMemo(() => new Map(config.eventTypes.map(item => [item.id, item.label])), [config.eventTypes]);
  const metaOf = (resource: ResourceConfig) => [
    resource.period?.year === undefined ? '' : `${resource.period.year} 年`,
    eventLabels.get(resource.eventType ?? '') ?? '',
  ].filter(Boolean).join(' · ');

  const resources = useMemo(() => {
    const normalized = query.trim().toLocaleLowerCase();
    return config.resources.filter(resource => {
      const matchesKind = kind === 'all' || resource.kind === kind;
      const matchesEvent = eventType === 'all' || resource.eventType === eventType;
      // 搜索覆盖标题、说明与**原始文件名/路径**：查"图纸""核心物项""1980"这类线索时不需要知道站内命名。
      const haystack = `${resource.title}${resource.description}${resource.source?.path ?? ''}${resource.source?.dossier ?? ''}`.toLocaleLowerCase();
      const matchesQuery = !normalized || haystack.includes(normalized);
      return matchesKind && matchesEvent && matchesScope(resource, scope) && matchesQuery;
    });
  }, [config.resources, eventType, kind, query, scope]);

  const timeline = useMemo(() => {
    const byYear = new Map<number, ResourceConfig[]>();
    const undated: ResourceConfig[] = [];
    for (const resource of resources) {
      const year = resource.period?.year;
      if (year === undefined) {
        undated.push(resource);
        continue;
      }
      const list = byYear.get(year);
      if (list) list.push(resource);
      else byYear.set(year, [resource]);
    }
    return [
      ...[...byYear.entries()].sort((left, right) => left[0] - right[0])
        .map(([year, items]) => ({ key: String(year), label: `${year} 年`, summary: '', items })),
      ...(undated.length ? [{ key: 'undated', label: UNKNOWN_YEAR_LABEL, summary: '', items: undated }] : []),
    ];
  }, [resources]);

  const grouped = useMemo(() => {
    const groups = config.collections.map(collection => ({
      key: collection.id,
      label: collection.label,
      summary: collection.summary,
      items: resources.filter(resource => resource.collectionIds.includes(collection.id)),
    }));
    const loose = resources.filter(resource => resource.collectionIds.length === 0);
    if (loose.length) groups.push({ key: 'none', label: UNCATALOGUED_LABEL, summary: '', items: loose });
    return groups.filter(group => group.items.length > 0);
  }, [config.collections, resources]);

  if (selected) {
    const sourcePath = (location.state as { pathname?: unknown } | null)?.pathname;
    // 同类型的一批资料：图片查看器据此做左右滑动翻阅（不跨类型混排，行为可预期）。
    const siblings = resources.filter(item => item.kind === selected.kind);
    const index = siblings.findIndex(item => item.id === selected.id);
    const goTo = (offset: number) => {
      const target = siblings[index + offset];
      if (!target) return;
      saveScroll();
      // replace：连续翻看不把历史记录堆满；带上原 state，"返回"仍然回到进来时的列表/设备页。
      navigate(`/archive/${target.id}`, { replace: true, state: location.state });
    };
    return (
      <ResourceViewer
        resource={selected}
        onBack={() => navigate(typeof sourcePath === 'string' && sourcePath.startsWith('/') ? sourcePath : '/archive')}
        siblings={siblings.length > 1 && index >= 0
          ? { position: `${index + 1} / ${siblings.length}`, prev: siblings[index - 1], next: siblings[index + 1], onGo: goTo }
          : undefined}
      />
    );
  }

  const sections = view === 'timeline' ? timeline : grouped;

  return (
    <section className="archive-page">
      <header className="feature-hero compact">
        <span>KNOWLEDGE BASE</span>
        <div className="archive-hero-row">
          <h1>数字档案</h1>
          {/* 视图是"怎么排布这批资料"，放在标题行；筛选才是"看哪些资料"。 */}
          <div className="archive-view-switch" role="group" aria-label="档案视图">
            {views.map(item => (
              <button type="button" key={item.value} aria-pressed={view === item.value} className={view === item.value ? 'is-active' : undefined} onClick={() => setView(item.value)}>{item.label}</button>
            ))}
          </div>
        </div>
        <p>按年代、事件与归属检索</p>
      </header>
      <label className="archive-search"><Search /><span className="sr-only">搜索数字档案</span><input type="search" aria-label="搜索数字档案" value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索标题、说明或原始文件名" /></label>
      <div className="archive-controls">
        <div className="archive-filters" aria-label="档案类型">
          {kindFilters.map(filter => (
            <button type="button" key={filter.value} aria-pressed={kind === filter.value} className={kind === filter.value ? 'is-active' : undefined} onClick={() => setKind(filter.value)}>{filter.label}</button>
          ))}
        </div>
        <div className="archive-facet-row" aria-label="事件类型">
          <button type="button" aria-pressed={eventType === 'all'} className={eventType === 'all' ? 'is-active' : undefined} onClick={() => setEventType('all')}>全部</button>
          {config.eventTypes.map(item => (
            <button type="button" key={item.id} aria-pressed={eventType === item.id} className={eventType === item.id ? 'is-active' : undefined} onClick={() => setEventType(item.id)}>{item.label}</button>
          ))}
        </div>
        <div className="archive-facet-row" aria-label="资料归属">
          {scopeFilters.map(filter => (
            <button type="button" key={filter.value} aria-pressed={scope === filter.value} className={scope === filter.value ? 'is-active' : undefined} onClick={() => setScope(filter.value)}>{filter.label}</button>
          ))}
        </div>
      </div>
      <div className="archive-results">
        {view === 'grid' && (
          <div className="archive-grid">
            {resources.map(resource => (
              <ResourceCard key={resource.id} resource={resource} meta={metaOf(resource)} onOpen={() => openResource(resource.id)} />
            ))}
          </div>
        )}
        {view !== 'grid' && sections.map(section => (
          <section className="archive-era" key={section.key} aria-label={section.label}>
            <header><strong>{section.label}</strong><span>{section.items.length} 项</span></header>
            {section.summary && <p>{section.summary}</p>}
            <div className="archive-grid">
              {section.items.map(resource => (
                <ResourceCard key={resource.id} resource={resource} meta={metaOf(resource)} onOpen={() => openResource(resource.id)} />
              ))}
            </div>
          </section>
        ))}
        {!resources.length && <p className="empty-state">没有匹配的档案</p>}
      </div>
    </section>
  );
}
